// ===== EDIT THIS LIST =====
// One entry per department. projectGid = the Asana project's numeric ID
// (open the project in Asana; the number in the URL .../0/<projectGid>/list is it).
const DEPARTMENTS = [
  { department: 'PR',                 projectGid: 'REPLACE_PROJECT_GID_1' },
  { department: 'Legal',              projectGid: 'REPLACE_PROJECT_GID_2' },
  { department: 'Customer Success',   projectGid: 'REPLACE_PROJECT_GID_3' },
  { department: 'Operations',         projectGid: 'REPLACE_PROJECT_GID_4' },
  { department: 'HR / Leadership',    projectGid: 'REPLACE_PROJECT_GID_5' }
];

return DEPARTMENTS.map(d => ({ json: d }));

// Buckets per department, computed from the Asana task list for THIS item.
const dept = $('Define Departments').item.json.department;
const tasks = ($json.data) || [];

const now    = new Date();
const today  = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const in7    = new Date(today); in7.setDate(in7.getDate() + 7);
const last7  = new Date(today); last7.setDate(last7.getDate() - 7);

let completedLastWeek = 0, overdue = 0, upcoming = 0, totalOpen = 0;

for (const t of tasks) {
  const completed   = !!t.completed;
  const completedAt = t.completed_at ? new Date(t.completed_at) : null;
  const dueOn       = t.due_on ? new Date(t.due_on + 'T00:00:00') : null;

  if (completed) {
    if (completedAt && completedAt >= last7 && completedAt <= now) completedLastWeek++;
  } else {
    totalOpen++;
    if (dueOn && dueOn <  today) overdue++;
    if (dueOn && dueOn >= today && dueOn <= in7) upcoming++;
  }
}

// Monday of the current week as the snapshot date
const wk  = new Date(today);
const dow = wk.getDay();                 // 0=Sun .. 6=Sat
wk.setDate(wk.getDate() + (dow === 0 ? -6 : 1 - dow));
const weekOf = wk.toISOString().slice(0, 10);

return { json: {
  'Department':          dept,
  'Week Of':             weekOf,
  'Completed Last Week': completedLastWeek,
  'Overdue':             overdue,
  'Upcoming Next Week':  upcoming,
  'Total Open':          totalOpen,
  'Snapshot Key':        weekOf + '|' + dept
} };
